import{_ as a,H as o,f as t,i as s}from"./chunks/framework.CBmkDW73.js";const h=JSON.parse('{"title":"plan","description":"","frontmatter":{},"headers":[],"relativePath":"zh/skills/plan.md","filePath":"zh/skills/plan.md"}'),l={name:"zh/skills/plan.md"};function d(c,e,n,i,p,r){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="plan" tabindex="-1">plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;plan&quot;">​</a></h1><p><code>plan</code> 技能将已批准的规范拆解为 <code>docs/staging/plans/YYYY-MM-DD-&lt;topic&gt;.md</code> 中的可执行里程碑任务。只引用规范路径，不复述背景、架构或决策理由。</p><h2 id="滚动波浪与多模块拓扑" tabindex="-1">滚动波浪与多模块拓扑 <a class="header-anchor" href="#滚动波浪与多模块拓扑" aria-label="Permalink to &quot;滚动波浪与多模块拓扑&quot;">​</a></h2><ul><li><strong>滚动波浪（Rolling wave）</strong>：当规范引用 <code>docs/ROADMAP.md</code> 中的 <code>milestone: MN</code> 时，仅展开当前里程碑，其余里程碑保留单行桩（stub）。<code>ship</code> 完成后确认下一个里程碑再继续展开；仅当目标发生实质变化时回到 <code>design</code>。</li><li><strong>多模块拓扑</strong>：若声明了 <code>topology=multi-module</code>，请先阅读<a href="./multi-module.html">多模块协议</a>，并在协调者（Coordinator）工作区计划顶部写入模式声明块（<code>topology: multi-module</code>、<code>change-set</code>、<code>coordinator</code>、<code>repos</code>、各模块计划路径与集成任务）。每个任务唯一归属一个 <code>repository:</code> 与 <code>module:</code>，按「契约 → 消费方 → 模块本地验收 → 集成验收 → 依赖序提交」排列。</li></ul><h2 id="里程碑任务-每项-30–60-分钟" tabindex="-1">里程碑任务（每项 30–60 分钟） <a class="header-anchor" href="#里程碑任务-每项-30–60-分钟" aria-label="Permalink to &quot;里程碑任务（每项 30–60 分钟）&quot;">​</a></h2><p>每条任务必须写成复选框（<code>- [ ] T&lt;n&gt;: &lt;名称&gt;</code>），绝不使用标题，并附带声明式字段：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>goal:       &lt;一句话目标&gt;</span></span>
<span class="line"><span>files:      &lt;涉及路径&gt;</span></span>
<span class="line"><span>acceptance: &lt;可执行测试、命令或显式手工核验步骤&gt;</span></span>
<span class="line"><span>spec:       &lt;docs/staging/specs/...#anchor&gt;</span></span></code></pre></div><p>仅当共享契约、状态与验收边界均已闭合且写入范围互不重叠时，才标记 <code>[parallel] T3, T4, T5</code>。原子化操作步骤推迟到 <code>subagents</code> 派发时再展开。</p><h2 id="移交关卡" tabindex="-1">移交关卡 <a class="header-anchor" href="#移交关卡" aria-label="Permalink to &quot;移交关卡&quot;">​</a></h2><p><code>&lt;gate&gt;</code> 移交给 <code>tdd</code> 或 <code>subagents</code> 之前，<code>docs/staging/plans/YYYY-MM-DD-&lt;topic&gt;.md</code>（多模块场景还须包含各受影响模块的计划文件）必须已在磁盘就绪并获得用户确认。 <code>&lt;/gate&gt;</code></p>`,10)])])}const u=a(l,[["render",d]]);export{h as __pageData,u as default};
